"""Final thumbnail generated by openai/gpt-image-2.5-sunburst with the Arabic phrase inside the image."""
import base64
import inspect
import io
import json
import re
import sys
from pathlib import Path

import pytest
from PIL import Image

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "scripts"))

import failure_registry as registry  # noqa: E402
import image_generate  # noqa: E402
import pipeline  # noqa: E402
import sunburst_thumbnail as sunburst  # noqa: E402
import vercel_gateway as gateway  # noqa: E402

TEXT = "أزقة طرابلس البيضاء"
KEY = "test-gateway-key-0123456789-not-real"


def noisy_png(size=(1536, 1024), fmt="PNG") -> bytes:
    image = Image.effect_noise(size, 80).convert("RGB")
    buffer = io.BytesIO()
    image.save(buffer, format=fmt)
    return buffer.getvalue()


class Net:
    """Fake gateway. ``script`` is a list of (status, body) answers consumed in order; the last one repeats."""

    def __init__(self, script=None):
        self.calls = []
        self.script = script or [(200, json.dumps({"data": [{"b64_json": base64.b64encode(noisy_png()).decode()}]}).encode())]

    def __call__(self, method, url, headers, body, timeout):
        self.calls.append({"method": method, "url": url, "headers": headers, "body": body})
        index = min(len(self.calls) - 1, len(self.script) - 1)
        return self.script[index]


def ok_body(data=None):
    return 200, json.dumps({"data": [{"b64_json": base64.b64encode(data or noisy_png()).decode()}]}).encode()


def err_body(status, message="x"):
    return status, json.dumps({"error": {"message": message}}).encode()


@pytest.fixture
def story(tmp_path, monkeypatch):
    monkeypatch.setenv("AI_GATEWAY_API_KEY", KEY)
    monkeypatch.setattr(sunburst.time, "sleep", lambda s: None)
    folder = tmp_path / "story"
    folder.mkdir()
    Image.effect_noise((1920, 1080), 60).convert("RGB").save(folder / "10_background.png")
    return folder


def run(story, net, monkeypatch):
    monkeypatch.setattr(gateway, "transport", net)
    return sunburst.generate(story, TEXT)


def test_exact_model_secret_and_endpoint(story, monkeypatch):
    net = Net()
    run(story, net, monkeypatch)
    assert gateway.MODEL == "openai/gpt-image-2.5-sunburst" and gateway.SECRET_NAME == "AI_GATEWAY_API_KEY"
    call = net.calls[0]
    assert call["method"] == "POST" and call["url"] == "https://ai-gateway.vercel.sh/v1/images/edits"
    assert call["headers"]["Authorization"] == f"Bearer {KEY}"
    assert b'name="model"\r\n\r\nopenai/gpt-image-2.5-sunburst\r\n' in call["body"]
    assert b'"models"' not in call["body"]  # no fallback model list


def test_the_text_free_background_is_the_reference_image(story, monkeypatch):
    net = Net()
    run(story, net, monkeypatch)
    reference = (story / "10_background.png").read_bytes()
    assert reference in net.calls[0]["body"] and b'name="image"; filename="reference.png"' in net.calls[0]["body"]


def test_prompt_contains_the_exact_arabic_phrase_and_forbids_everything_else(story, monkeypatch):
    prompt = sunburst.build_prompt(TEXT)
    assert f"EXACT ARABIC TEXT: «{TEXT}»" in prompt
    assert "Render exactly this Arabic phrase and no other text." in prompt
    for required in ("Preserve the spelling exactly", "right-to-left", "Do not translate it", "paraphrase",
                     "Do not add any other text", "no Latin letters", "no gibberish", "no duplicated title",
                     "no watermark", "no logo", "text box", "banner", "pill", "opaque panel", "black card",
                     "black rectangle", "caption bar", "artificial dark block", "integrated naturally"):
        assert required in prompt
    net = Net()
    run(story, net, monkeypatch)
    assert TEXT.encode("utf-8") in net.calls[0]["body"]


def test_final_thumbnail_is_1280x720_jpeg_at_the_expected_path_and_background_is_untouched(story, monkeypatch):
    before = (story / "10_background.png").read_bytes()
    record = run(story, Net(), monkeypatch)
    thumbnail = story / "11_thumbnail_base.jpg"
    with Image.open(thumbnail) as image:
        assert image.size == (1280, 720) and image.format == "JPEG"
    assert (story / "10_background.png").read_bytes() == before  # the video background stays text-free
    assert record["thumbnail_generation_provider"] == "vercel_ai_gateway"
    assert record["thumbnail_model"] == "openai/gpt-image-2.5-sunburst"
    assert record["thumbnail_text_render_method"] == "native_in_generated_image"
    assert record["thumbnail_text_ocr_verified"] is False  # honest: no automatic Arabic spelling check
    assert record["thumbnail_attempts"] == 1


def test_non_16_9_output_is_cropped_deterministically_not_distorted():
    for size in ((1536, 1024), (1024, 1024), (1920, 1080), (2000, 700)):
        image = sunburst.finalize_image(noisy_png(size))
        assert image.size == (1280, 720)


def test_first_valid_candidate_stops_generation(story, monkeypatch):
    net = Net()
    run(story, net, monkeypatch)
    assert len(net.calls) == 1


def test_invalid_candidates_are_retried_up_to_four_times_then_stop(story, monkeypatch):
    net = Net([ok_body(b"not an image")])
    with pytest.raises(gateway.GatewayError) as caught:
        run(story, net, monkeypatch)
    assert sunburst.MAX_SUNBURST_THUMBNAIL_ATTEMPTS == 4 and len(net.calls) == 4
    assert caught.value.code == gateway.REQUEST_FAILED
    log = json.loads((story / "logs" / "thumbnail_attempts.json").read_text(encoding="utf-8"))
    assert [item["attempt"] for item in log] == [1, 2, 3, 4] and KEY not in json.dumps(log)


def test_a_later_good_candidate_succeeds_without_extra_calls(story, monkeypatch):
    net = Net([ok_body(b"junk"), ok_body()])
    record = run(story, net, monkeypatch)
    assert len(net.calls) == 2 and record["thumbnail_attempts"] == 2


def test_rejected_size_tries_the_next_size_without_using_an_attempt(story, monkeypatch):
    net = Net([err_body(400, "invalid size"), ok_body()])
    record = run(story, net, monkeypatch)
    assert record["thumbnail_attempts"] == 1 and len(net.calls) == 2
    assert b"1536x864" in net.calls[0]["body"] and b"1536x1024" in net.calls[1]["body"]


@pytest.mark.parametrize("status,message", [(402, "payment required"), (429, "insufficient credits"),
                                            (403, "free credit quota exhausted")])
def test_quota_or_credit_exhaustion_stops_with_the_registered_code_and_no_fallback(story, monkeypatch, status, message):
    net = Net([err_body(status, message)])
    with pytest.raises(gateway.GatewayError) as caught:
        run(story, net, monkeypatch)
    assert caught.value.code == "VERCEL_FREE_QUOTA_EXHAUSTED" and len(net.calls) == 1
    assert {urlparse_host(call["url"]) for call in net.calls} == {"ai-gateway.vercel.sh"}  # no OpenAI / other provider
    assert registry.extract_error_code(caught.value) == "VERCEL_FREE_QUOTA_EXHAUSTED"
    assert registry.REGISTRY["VERCEL_FREE_QUOTA_EXHAUSTED"].waiting_for_quota


def urlparse_host(url):
    return re.match(r"https://([^/]+)/", url).group(1)


def test_auth_failure_and_missing_key_stop_immediately(story, monkeypatch):
    net = Net([err_body(401)])
    with pytest.raises(gateway.GatewayError) as caught:
        run(story, net, monkeypatch)
    assert caught.value.code == "VERCEL_AUTH_FAILED" and len(net.calls) == 1
    monkeypatch.delenv("AI_GATEWAY_API_KEY")
    net = Net()
    with pytest.raises(gateway.GatewayError) as caught:
        run(story, net, monkeypatch)
    assert caught.value.code == "VERCEL_KEY_MISSING" and net.calls == []
    assert registry.REGISTRY["VERCEL_KEY_MISSING"].owner_action_required


def test_error_messages_never_contain_the_key(story, monkeypatch):
    monkeypatch.setattr(gateway, "transport", Net([err_body(402, f"credits for {KEY} are gone")]))
    with pytest.raises(gateway.GatewayError) as caught:
        sunburst.generate(story, TEXT)
    assert KEY not in str(caught.value) and "[redacted]" in str(caught.value)


def test_no_text_is_drawn_by_the_new_thumbnail_path():
    for module in (sunburst, gateway):
        source = inspect.getsource(module)
        for forbidden in ("ImageDraw", ".text(", "rounded_rectangle", "drawtext", "arabic_reshaper", "Pango",
                          "api.openai.com", "BYOK", "google", "pollinations", "cloudflare"):
            assert forbidden not in source, (module.__name__, forbidden)
    final = inspect.getsource(image_generate.build_final_thumbnail)
    for forbidden in ("render_thumbnail", "ImageDraw", ".text("):
        assert forbidden not in final


def test_old_renderer_is_not_called_on_the_production_path(story, monkeypatch):
    monkeypatch.setattr(image_generate, "render_thumbnail", lambda *a, **k: pytest.fail("old text renderer called"))
    monkeypatch.setattr(gateway, "transport", Net())
    record, status = image_generate.build_final_thumbnail(story, story / "10_background.png", TEXT)
    assert status == "passed" and record["thumbnail_text_render_method"] == "native_in_generated_image"
    generate_source = inspect.getsource(image_generate.generate)
    assert "render_thumbnail(" not in generate_source


def test_legacy_episode_without_thumbnail_text_makes_no_gateway_call(story, monkeypatch):
    net = Net()
    monkeypatch.setattr(gateway, "transport", net)
    record, status = image_generate.build_final_thumbnail(story, story / "10_background.png", "")
    assert status == "legacy_no_text" and record == {} and net.calls == []


def test_accepted_background_is_reused_when_only_the_thumbnail_failed(story, monkeypatch):
    prompt = "A lantern lit alley."
    (story / "08_image_prompt_en.txt").write_text(prompt, encoding="utf-8")
    import hashlib
    background = story / "10_background.png"
    (story / "15_metadata.json").write_text(json.dumps({
        "thumbnail_text": TEXT, "image_generation_status": "passed",
        "image_prompt_sha256": hashlib.sha256(prompt.encode()).hexdigest(),
        "image_sha256": hashlib.sha256(background.read_bytes()).hexdigest(), "image_model": "m"}), encoding="utf-8")
    monkeypatch.setattr(image_generate, "generate_cloudflare", lambda *a, **k: pytest.fail("background generated again"))
    monkeypatch.setattr(image_generate, "generate_pollinations", lambda *a, **k: pytest.fail("fallback used"))
    monkeypatch.setattr(gateway, "transport", Net())
    image_generate.generate(story)
    metadata = json.loads((story / "15_metadata.json").read_text(encoding="utf-8"))
    assert metadata["thumbnail_text_render_status"] == "passed" and (story / "11_thumbnail_base.jpg").is_file()
    assert metadata["thumbnail_model"] == "openai/gpt-image-2.5-sunburst"


def test_video_still_renders_from_the_text_free_background_and_pipeline_expects_the_same_files():
    assert 'story / "10_background.png"' in inspect.getsource(pipeline.render)
    assert '"11_thumbnail_base.jpg"' in inspect.getsource(pipeline.background)
    source = inspect.getsource(image_generate.generate)
    assert 'image.save(background, format="PNG"' in source and "thumbnail" not in source.split("image.save(background")[1].split("historical_accuracy_gate")[0]


def test_no_paid_or_direct_provider_and_no_model_list_in_the_gateway_client():
    source = inspect.getsource(gateway)
    assert source.count("openai/gpt-image-2.5-sunburst") == 1
    for forbidden in ("api.openai.com", '"models":', "fallback", "purchase", "billing/"):
        assert forbidden not in source.replace("QUOTA_WORDS", "")


def test_production_and_review_workflows_pass_the_secret_only_via_env_and_never_dump_it():
    for name in ("production.yml", "review.yml"):
        text = (ROOT / ".github" / "workflows" / name).read_text(encoding="utf-8")
        assert text.count("AI_GATEWAY_API_KEY: ${{ secrets.AI_GATEWAY_API_KEY }}") == 1
        assert "printenv" not in text and "env | sort" not in text and "set -x" not in text
